ALTER TABLE "budget_accounts" ADD CONSTRAINT "budget_accounts_amounts_ck" CHECK ("budget_accounts"."limit_minor" >= 0 and "budget_accounts"."reserved_minor" >= 0 and "budget_accounts"."spent_minor" >= 0);--> statement-breakpoint
